56	    fn make_shard_state<S>(
57	        &self,
58	        local_ip_addr: &str,
59	        shard_id: ShardId,
60	        storage: S,
61	    ) -> (WorkerState<S>, ShardId, ShardConfig)
62	    where
63	        S: Storage + Clone + Send + Sync + 'static,
64	    {
65	        let shard = self.server_config.internal_network.shard(shard_id);
66	        info!("Shard booted on {}", shard.host);
67	        info!(
68	            "Public key: {}",
69	            self.server_config.validator_secret.public()
70	        );
71	        let state = WorkerState::new(
72	            format!("Shard {} @ {}:{}", shard_id, local_ip_addr, shard.port),
73	            Some((
74	                self.server_config.validator_secret.copy(),
75	                self.server_config.account_secret.copy(),
76	            )),
77	            storage,
78	            self.max_loaded_chains,
79	        )
80	        .with_allow_inactive_chains(false)
81	        .with_allow_messages_from_deprecated_epochs(false)
82	        .with_grace_period(self.grace_period);
83	        (state, shard_id, shard.clone())
84	    }
