86	    fn spawn_simple<S>(
87	        &self,
88	        listen_address: &str,
89	        states: Vec<(WorkerState<S>, ShardId, ShardConfig)>,
90	        protocol: simple::TransportProtocol,
91	        shutdown_signal: CancellationToken,
92	    ) -> JoinSet<()>
93	    where
94	        S: Storage + Clone + Send + Sync + 'static,
95	    {
96	        let mut join_set = JoinSet::new();
97	        let handles = FuturesUnordered::new();
98	
99	        let internal_network = self
100	            .server_config
101	            .internal_network
102	            .clone_with_protocol(protocol);
103	
104	        for (state, shard_id, shard) in states {
105	            let internal_network = internal_network.clone();
106	            let cross_chain_config = self.cross_chain_config.clone();
107	            let listen_address = listen_address.to_owned();
108	
109	            #[cfg(with_metrics)]
110	            if let Some(port) = shard.metrics_port {
111	                Self::start_metrics(&listen_address, port, shutdown_signal.clone());
112	            }
113	
114	            let server_handle = simple::Server::new(
115	                internal_network,
116	                listen_address,
117	                shard.port,
118	                state,
119	                shard_id,
120	                cross_chain_config,
121	            )
122	            .spawn(shutdown_signal.clone(), &mut join_set);
123	
124	            handles.push(
125	                server_handle
126	                    .join()
127	                    .inspect_err(move |error| {
128	                        error!("Error running server for shard {shard_id}: {error:?}")
129	                    })
130	                    .map(|_| ()),
131	            );
132	        }
133	
134	        join_set.spawn_task(handles.collect::<()>());
135	
136	        join_set
137	    }
